package com.fuelflex.platform.operations.service;import java.math.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.fuelflex.platform.common.exception.*;import com.fuelflex.platform.common.security.AuthorizationService;import com.fuelflex.platform.operations.dto.InternalConsumptionDtos.*;import com.fuelflex.platform.operations.entity.*;import com.fuelflex.platform.operations.repository.*;import com.fuelflex.platform.role.entity.Role;import com.fuelflex.platform.sale.service.*;import com.fuelflex.platform.station.service.StationAccessService;import com.fuelflex.platform.user.entity.User;import lombok.RequiredArgsConstructor;
@Service@RequiredArgsConstructor@Transactional public class InternalConsumptionService{private final AuthorizationService authorization;private final PumpShiftAssignmentRepository shifts;private final OperationalDayRepository days;private final InternalConsumptionRepository consumptions;private final InternalConsumptionStockMovementRepository movements;private final PosConfigurationResolver pricing;private final StationAccessService access;
 public Response create(UUID shiftId,CreateRequest request){User actor=manager();PumpShiftAssignment shift=shifts.lockByIdAndOrganizationId(shiftId,actor.getOrganization().getId()).orElseThrow(()->new ResourceNotFoundException("Affectation introuvable."));access.checkStationAccess(actor,shift.getOperationalDay().getStation().getId());if(shift.getStatus()!=OperationalStatus.OPEN)throw new ConflictException("La consommation interne exige une affectation ouverte.");BigDecimal quantity=scale(request.quantity());ResolvedPosContext context=pricing.resolveInternal(shift);InternalConsumption c=new InternalConsumption();c.setOrganization(shift.getOperationalDay().getOrganization());c.setStation(shift.getOperationalDay().getStation());c.setOperationalDay(shift.getOperationalDay());c.setShiftAssignment(shift);c.setPumpAttendant(shift.getPumpAttendant());c.setFuelMeter(shift.getFuelMeter());c.setTank(context.tank());c.setProduct(context.product());c.setTariffCategory(context.tariffCategory());c.setQuantity(quantity);c.setUnitPrice(context.unitPrice());c.setTotalAmount(quantity.multiply(context.unitPrice()).setScale(3,RoundingMode.HALF_UP));c.setUsageBeneficiary(clean(request.usageBeneficiary()));c.setObservation(clean(request.observation()));c.setRecordedBy(actor);c=consumptions.saveAndFlush(c);InternalConsumptionStockMovement m=new InternalConsumptionStockMovement();m.setInternalConsumption(c);m.setTank(c.getTank());m.setProduct(c.getProduct());m.setQuantity(quantity);movements.saveAndFlush(m);return response(c);}
 @Transactional(readOnly=true)public List<Response> byShift(UUID id){User a=viewer();PumpShiftAssignment s=shifts.findByIdAndOperationalDayOrganizationId(id,a.getOrganization().getId()).orElseThrow(()->new ResourceNotFoundException("Affectation introuvable."));access.checkStationAccess(a,s.getOperationalDay().getStation().getId());return consumptions.findByShiftAssignmentIdOrderByRecordedAtAsc(id).stream().map(this::response).toList();}
 @Transactional(readOnly=true)public List<Response> byDay(UUID id){User a=viewer();OperationalDay d=days.findByIdAndOrganizationId(id,a.getOrganization().getId()).orElseThrow(()->new ResourceNotFoundException("Journée introuvable."));access.checkStationAccess(a,d.getStation().getId());return consumptions.findByOperationalDayIdOrderByRecordedAtAsc(id).stream().map(this::response).toList();}
 private Response response(InternalConsumption c){var m=c.getFuelMeter();var point=m.getDispensingPoint();var pump=point==null?m.getPump():point.getPump();return new Response(c.getId(),c.getOrganization().getId(),c.getStation().getId(),c.getStation().getName(),c.getOperationalDay().getId(),c.getShiftAssignment().getId(),c.getPumpAttendant().getId(),c.getPumpAttendant().getFirstName()+" "+c.getPumpAttendant().getLastName(),pump.getId(),pump.getName(),m.getId(),m.getName(),c.getTank().getId(),c.getTank().getName(),c.getProduct().getId(),c.getProduct().getName(),c.getTariffCategory().getId(),c.getTariffCategory().getCode(),c.getQuantity(),c.getUnitPrice(),c.getTotalAmount(),c.getUsageBeneficiary(),c.getObservation(),c.getRecordedBy().getId(),c.getRecordedAt());}
 private User viewer(){User a=authorization.getAuthenticatedUser();if(a==null||a.getOrganization()==null||a.getRoles().stream().filter(Role::isActive).noneMatch(r->Set.of("MANAGER","SUPERVISOR").contains(r.getCode())))throw new ForbiddenException("Accès opérationnel refusé.");return a;}private User manager(){User a=viewer();if(a.getRoles().stream().filter(Role::isActive).noneMatch(r->"MANAGER".equals(r.getCode())))throw new ForbiddenException("Rôle requis: MANAGER");return a;}private BigDecimal scale(BigDecimal v){try{return v.setScale(3,RoundingMode.UNNECESSARY);}catch(ArithmeticException e){throw new BusinessException("La quantité accepte au maximum trois décimales.");}}private String clean(String v){return v==null||v.isBlank()?null:v.trim().replaceAll("\\s+"," ");}}
